        return new Source("{% extends 'front/base.html.twig' %}

{% block title %}New Post — MindBoost{% endblock %}

{% block body %}
<div class=\"row justify-content-center\">
    <div class=\"col-md-8\">
        <nav aria-label=\"breadcrumb\" class=\"mb-3\">
            <ol class=\"breadcrumb\">
                <li class=\"breadcrumb-item\"><a href=\"{{ path('front_post_index') }}\">Posts</a></li>
                <li class=\"breadcrumb-item active\">New Post</li>
            </ol>
        </nav>
        <div class=\"card\">
            <div class=\"card-body\">
                <h5 class=\"fw-bold mb-4\"><i class=\"bi bi-plus-circle me-2 text-primary\"></i>Create New Post</h5>
                {{ form_start(form, {'attr': {'novalidate': 'novalidate'}}) }}
                {{ form_errors(form) }}
                <div class=\"mb-3\">
                    {{ form_label(form.title) }}
                    {{ form_widget(form.title) }}
                    {{ form_errors(form.title) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_label(form.content) }}
                    {{ form_widget(form.content) }}
                    {{ form_errors(form.content) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_label(form.tag) }}
                    {{ form_widget(form.tag) }}
                    {{ form_errors(form.tag) }}
                </div>
                <div class=\"mb-3\">
                    {{ form_label(form.imageUrl) }}
                    {{ form_widget(form.imageUrl) }}
                    {{ form_errors(form.imageUrl) }}
                </div>
                <div class=\"d-flex gap-2\">
                    <button type=\"submit\" class=\"btn btn-primary\"><i class=\"bi bi-check-lg me-1\"></i>Create Post</button>
                    <a href=\"{{ path('front_post_index') }}\" class=\"btn btn-outline-secondary\">Cancel</a>
                </div>
                {{ form_end(form) }}
            </div>
        </div>
    </div>
</div>
{% endblock %}
